* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
}

a.skip-link {
  position: absolute;
  left: 8px;
  top: -40px;
  background: var(--accent);
  color: var(--accent-contrast);
  padding: 8px 12px;
  border-radius: 6px;
  text-decoration: none;
  font-weight: 600;
  z-index: 100;
}
a.skip-link:focus { top: 8px; }

.page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.site-header {
  padding: 1rem 1.25rem;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
}
.site-header .brand {
  font-weight: 700;
  letter-spacing: 0.02em;
  color: var(--text);
}

main {
  flex: 1;
  padding: 2rem 1rem;
  display: flex;
  justify-content: center;
}

.card {
  width: 100%;
  max-width: 560px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.75rem;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
}

h1 {
  margin: 0 0 0.5rem;
  font-size: 1.6rem;
}

.lede {
  margin: 0 0 1.5rem;
  color: var(--text-muted);
}

.required-legend {
  margin: 0 0 1rem;
  color: var(--text-muted);
  font-size: 0.9rem;
}
.required-marker {
  color: var(--accent);
  margin-left: 2px;
}

.form-field {
  margin-bottom: 1.25rem;
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: 0.4rem;
  color: var(--text);
}

input[type="text"],
input[type="email"],
input[type="tel"] {
  width: 100%;
  padding: 0.65rem 0.75rem;
  font: inherit;
  color: var(--text);
  background: var(--surface-2);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  transition: border-color 0.15s, box-shadow 0.15s;
}

input::placeholder { color: #7d869c; }

input:hover { border-color: #7785a3; }

input:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-color: var(--accent);
}

input[aria-invalid="true"] {
  border-color: var(--error);
  background: var(--error-bg);
}

.help-text {
  margin: 0.4rem 0 0;
  color: var(--text-muted);
  font-size: 0.875rem;
}

.error-text {
  margin: 0.4rem 0 0;
  color: var(--error);
  font-size: 0.9rem;
  font-weight: 600;
}

.actions {
  margin-top: 1.5rem;
  display: flex;
  gap: 0.75rem;
  align-items: center;
}

button[type="submit"] {
  background: var(--accent);
  color: var(--accent-contrast);
  border: 1px solid var(--accent-strong);
  padding: 0.7rem 1.25rem;
  font: inherit;
  font-weight: 700;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.15s, transform 0.05s;
}
button[type="submit"]:hover { background: var(--accent-strong); }
button[type="submit"]:active { transform: translateY(1px); }
button[type="submit"]:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.status {
  margin-top: 1rem;
  padding: 0.75rem 1rem;
  border-radius: 8px;
  background: #14321f;
  border: 1px solid #2f7a4d;
  color: #b8f1cc;
}
.status:empty { display: none; }

@media (forced-colors: active) {
  input, button[type="submit"], .card {
    border: 1px solid CanvasText;
  }
  input:focus-visible, button[type="submit"]:focus-visible {
    outline: 3px solid Highlight;
  }
}
