const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
// Accept digits, spaces, dashes, parentheses, dots, optional leading +. Require 7-15 digits.
const PHONE_RE = /^\+?[\d\s().-]{7,}$/;

function FormField({
  id,
  label,
  type = "text",
  value,
  onChange,
  required = false,
  autoComplete,
  helpText,
  error,
  inputRef,
  inputMode,
  placeholder,
}) {
  const helpId = helpText ? `${id}-help` : null;
  const errorId = `${id}-error`;
  const describedBy = [helpId, error ? errorId : null].filter(Boolean).join(" ") || undefined;

  return (
    <div className="form-field">
      <label htmlFor={id}>
        {label}
        {required && (
          <span className="required-marker" aria-hidden="true">*</span>
        )}
      </label>
      <input
        id={id}
        name={id}
        type={type}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        required={required}
        autoComplete={autoComplete}
        inputMode={inputMode}
        placeholder={placeholder}
        ref={inputRef}
        aria-describedby={describedBy}
        aria-invalid={error ? "true" : undefined}
      />
      {helpText && (
        <p className="help-text" id={helpId}>{helpText}</p>
      )}
      {error && (
        <p className="error-text" id={errorId}>Error: {error}</p>
      )}
    </div>
  );
}

function ContactForm() {
  const [values, setValues] = useState({ name: "", email: "", phone: "" });
  const [errors, setErrors] = useState({});
  const [status, setStatus] = useState("");

  const nameRef = useRef(null);
  const emailRef = useRef(null);
  const phoneRef = useRef(null);

  const setField = (key) => (val) => {
    setValues((v) => ({ ...v, [key]: val }));
    if (errors[key]) {
      setErrors((e) => {
        const next = { ...e };
        delete next[key];
        return next;
      });
    }
    if (status) setStatus("");
  };

  const validate = (vals) => {
    const e = {};
    if (!vals.name.trim()) {
      e.name = "Enter your full name.";
    }
    if (!vals.email.trim()) {
      e.email = "Enter your email address.";
    } else if (!EMAIL_RE.test(vals.email.trim())) {
      e.email = "Enter a valid email like name@example.com.";
    }
    if (vals.phone.trim() && !PHONE_RE.test(vals.phone.trim())) {
      e.phone = "Enter a valid phone number, for example +1 555 123 4567.";
    }
    return e;
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    const e = validate(values);
    setErrors(e);
    if (Object.keys(e).length > 0) {
      setStatus("");
      const order = ["name", "email", "phone"];
      const refs = { name: nameRef, email: emailRef, phone: phoneRef };
      const first = order.find((k) => e[k]);
      if (first && refs[first].current) refs[first].current.focus();
      return;
    }
    setStatus("Thanks! Your message has been received. We'll be in touch soon.");
    setValues({ name: "", email: "", phone: "" });
  };

  return (
    <form noValidate onSubmit={handleSubmit} aria-labelledby="form-heading">
      <p className="required-legend">
        Fields marked with <span className="required-marker" aria-hidden="true">*</span> are required.
      </p>

      <FormField
        id="name"
        label="Full name"
        required
        autoComplete="name"
        value={values.name}
        onChange={setField("name")}
        error={errors.name}
        inputRef={nameRef}
      />

      <FormField
        id="email"
        label="Email address"
        type="email"
        required
        autoComplete="email"
        value={values.email}
        onChange={setField("email")}
        error={errors.email}
        inputRef={emailRef}
        helpText="We'll only use this to reply to your request."
      />

      <FormField
        id="phone"
        label="Phone number (optional)"
        type="tel"
        autoComplete="tel"
        inputMode="tel"
        value={values.phone}
        onChange={setField("phone")}
        error={errors.phone}
        inputRef={phoneRef}
        helpText="Include country code if outside the US, e.g. +1 555 123 4567. Digits, spaces, dashes, and parentheses are accepted."
      />

      <div className="actions">
        <button type="submit">Send message</button>
      </div>

      <div className="status" role="status" aria-live="polite">{status}</div>
    </form>
  );
}

function App() {
  return (
    <div className="page">
      <a className="skip-link" href="#main">Skip to main content</a>
      <header className="site-header">
        <div className="brand">Acme Support</div>
      </header>
      <main id="main" tabIndex="-1">
        <section className="card" aria-labelledby="form-heading">
          <h1 id="form-heading">Contact support</h1>
          <p className="lede">
            Send us a message and our support team will get back to you.
          </p>
          <ContactForm />
        </section>
      </main>
    </div>
  );
}

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(<App />);
